89	    /**
90	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
91	     * owner's id, customer code, registration date and membership level, so audit side-effects can
92	     * be observed independently of the HTTP response.
93	     */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    /**
97	     * Monotonically increasing sequence number stamped on each {@code OWNER_CREATED} audit event, so
98	     * the immutable event stream has a strict total order across creates. Shared across all instances
99	     * and requests; incremented once per successful owner creation.
100	     */
101	    private static final java.util.concurrent.atomic.AtomicLong OWNER_EVENT_SEQ =
102	        new java.util.concurrent.atomic.AtomicLong(0);
103	
104	    /**
105	     * Common street-type abbreviations expanded during address normalization. Keys and values are
106	     * upper-cased, matching the state of the address after whitespace and case normalization.
107	     */
108	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
109	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
110	
111	    /**
112	     * Required national-number length per E.164 country calling code. After normalization the leading
113	     * country code is stripped and the remaining national digits must match the expected count exactly
114	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
115	     * here are only subject to the generic E.164 length bounds.
116	     */
117	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
118	        Map.of("1", 10, "61", 9);
119	
120	    /**
121	     * Fixed city-to-region table used to validate an owner's postcode. Cities not listed have no
122	     * known region and accept any well-formed (4-digit) postcode.
