245	    /**
246	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
247	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
248	     *
249	     * @return the trimmed idempotency key, or {@code null} when none was supplied
250	     */
251	    private String idempotencyKey() {
252	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
253	        if (value == null || value.isBlank()) {
254	            return null;
255	        }
256	        return value.strip();
257	    }
