408	    /**
409	     * Immutable, structured {@code OWNER_CREATED} audit event. Serialized to a compact JSON object
410	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} for the {@code AUDIT}
411	     * log. Being a record, once constructed its fields cannot change, so the emitted event is a faithful
412	     * snapshot of the owner at creation time.
413	     *
414	     * @param seq strictly increasing sequence number across all creates
415	     * @param ownerId the created owner's id
416	     * @param memberId the owner's current primary identifier at creation time
417	     * @param membershipLevel the owner's effective membership level at creation time
418	     */
419	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, Integer membershipLevel) {
420	
421	        private String toJson() {
422	            return "{\"seq\":" + seq
423	                + ",\"ownerId\":" + ownerId
424	                + ",\"memberId\":" + jsonValue(memberId)
425	                + ",\"membershipLevel\":" + membershipLevel
426	                + ",\"event\":\"OWNER_CREATED\"}";
427	        }
428	
429	        /** Renders a nullable string as a JSON string literal (with escaping) or {@code null}. */
430	        private static String jsonValue(String value) {
431	            if (value == null) {
432	                return "null";
433	            }
434	            StringBuilder sb = new StringBuilder(value.length() + 2);
435	            sb.append('"');
436	            for (int i = 0; i < value.length(); i++) {
437	                char c = value.charAt(i);
438	                switch (c) {
439	                    case '"' -> sb.append("\\\"");
440	                    case '\\' -> sb.append("\\\\");
441	                    case '\n' -> sb.append("\\n");
442	                    case '\r' -> sb.append("\\r");
443	                    case '\t' -> sb.append("\\t");
444	                    default -> sb.append(c);
445	                }
446	            }
447	            sb.append('"');
448	            return sb.toString();
449	        }
450	    }
