452	    /**
453	     * Builds the unified member id for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
454	     * where {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion}),
455	     * {@code FY} is the two-digit fiscal year of the owner's business-day-adjusted registration date,
456	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized
457	     * telephone concatenated with the last name (the same HASH8 used by the region-and-hash identity), and
458	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code '<REGION><FY><HASH8>'}. For
459	     * example an owner in the NSW postcode range registered in fiscal year 2026 gets an id such as
460	     * {@code 'NSW263F2A1B9C7'}.
461	     *
462	     * <p>When the computed member id collides with an existing owner's member id, it is de-duplicated by
463	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique across
464	     * all existing owners' member ids. The de-duplicated id is what gets assigned.
465	     *
466	     * @param owner the owner being created, whose postcode, city, registration date and last name feed the id
467	     * @param normalizedTelephone the owner's E.164-normalized telephone
468	     * @return the assigned member id, de-duplicated against existing owners if necessary
469	     */
470	    private String buildMemberId(Owner owner, String normalizedTelephone) {
471	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
472	        String fiscalYear = String.format("%02d", ownerMapper.fiscalYearValue(owner.getRegistrationDate()) % 100);
473	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
474	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
475	        String base = region + fiscalYear + hash8;
476	        String memberId = base + luhnCheckDigit(base);
477	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
478	            .map(Owner::getMemberId)
479	            .filter(id -> id != null)
480	            .collect(java.util.stream.Collectors.toSet());
481	        if (!existingIds.contains(memberId)) {
482	            return memberId;
483	        }
484	        int n = 2;
485	        while (existingIds.contains(memberId + "-" + n)) {
486	            n++;
487	        }
488	        return memberId + "-" + n;
489	    }
490	
491	    /**
492	     * Computes a single Luhn check digit (0-9) over the decimal digits contained in the given string.
493	     * Non-digit characters are ignored, so the check digit covers the region, fiscal-year and HASH8
494	     * digits of a member id's {@code '<REGION><FY><HASH8>'} base.
495	     *
496	     * @param value the string whose digits the check digit is computed over
497	     * @return the Luhn check digit, a single digit in {@code 0-9}
498	     */
499	    private int luhnCheckDigit(String value) {
500	        int sum = 0;
501	        boolean dbl = true;
502	        for (int i = value.length() - 1; i >= 0; i--) {
503	            char c = value.charAt(i);
504	            if (c < '0' || c > '9') {
505	                continue;
506	            }
507	            int d = c - '0';
508	            if (dbl) {
509	                d *= 2;
510	                if (d > 9) {
511	                    d -= 9;
512	                }
513	            }
514	            sum += d;
515	            dbl = !dbl;
516	        }
517	        return (10 - (sum % 10)) % 10;
518	    }
