520	    /**
521	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
522	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
523	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
524	     *
525	     * @param postcode the owner's postcode, may be {@code null}
526	     * @param city the owner's city, used to resolve the region when the postcode does not
527	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
528	     */
529	    private String deriveRegion(String postcode, String city) {
530	        if (postcode != null) {
531	            try {
532	                int value = Integer.parseInt(postcode.trim());
533	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
534	                    int[] range = entry.getValue();
535	                    if (value >= range[0] && value <= range[1]) {
536	                        return entry.getKey();
537	                    }
538	                }
539	            } catch (NumberFormatException ex) {
540	                // Not a numeric postcode; fall back to the city table below.
541	            }
542	        }
543	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
544	    }
545	
546	    /**
547	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
548	     * given input's UTF-8 bytes.
549	     *
550	     * @param input the string to hash
551	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
552	     */
553	    private String sha256Hex8(String input) {
554	        try {
555	            byte[] digest = MessageDigest.getInstance("SHA-256")
556	                .digest(input.getBytes(StandardCharsets.UTF_8));
557	            StringBuilder hex = new StringBuilder();
558	            for (int i = 0; i < 4; i++) {
559	                hex.append(String.format("%02X", digest[i]));
560	            }
561	            return hex.toString();
562	        } catch (NoSuchAlgorithmException ex) {
563	            throw new IllegalStateException("SHA-256 not available", ex);
564	        }
565	    }
