617	    /**
618	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
619	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
620	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
621	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
622	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
623	     * and returned exactly as given.
624	     *
625	     * @param postcode the submitted postcode, may be {@code null} when absent
626	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
627	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
628	     */
629	    private void validatePostcode(String postcode, String city) {
630	        if (postcode == null) {
631	            return;
632	        }
633	        if (!postcode.matches("[0-9]{4}")) {
634	            throw new InvalidOwnerFieldsException(List.of("postcode"));
635	        }
636	        String region = city == null ? null : CITY_REGION.get(city);
637	        if (region == null) {
638	            return;
639	        }
640	        int[] range = REGION_POSTCODES.get(region);
641	        int value = Integer.parseInt(postcode);
642	        if (value < range[0] || value > range[1]) {
643	            throw new InvalidOwnerFieldsException(List.of("postcode"));
644	        }
645	    }
