647	    /**
648	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
649	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
650	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
651	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
652	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
653	     *
654	     * @param telephone the raw telephone value from the submitted owner payload
655	     * @return the normalized E.164 telephone number
656	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
657	     */
658	    private String normalizeTelephone(String telephone) {
659	        String raw = telephone == null ? "" : telephone.strip();
660	        boolean hasCountryCode = raw.startsWith("+");
661	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
662	        String digits;
663	        if (hasCountryCode) {
664	            digits = cleaned.substring(1);
665	        } else {
666	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
667	            digits = "61" + national;
668	        }
669	        if (!digits.matches("[0-9]{8,15}")) {
670	            throw new InvalidOwnerFieldsException(List.of("telephone"));
671	        }
672	        validateNationalNumberLength(digits);
673	        return "+" + digits;
674	    }
675	
676	    /**
677	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
678	     * country calling code) has the exact length required for that country. The country code is matched
679	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
680	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
681	     *
682	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
683	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
684	     */
685	    private void validateNationalNumberLength(String digits) {
686	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
687	            String countryCode = entry.getKey();
688	            if (digits.startsWith(countryCode)) {
689	                int nationalLength = digits.length() - countryCode.length();
690	                if (nationalLength != entry.getValue()) {
691	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
692	                }
693	                return;
694	            }
695	        }
696	    }
697	
698	    /**
699	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
700	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
701	     * accepted value is trimmed and lower-cased before it is stored and returned.
702	     *
703	     * @param email the raw email value from the submitted owner payload, may be {@code null}
704	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
705	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
706	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
707	     */
708	    private String normalizeEmail(String email) {
709	        if (email == null) {
710	            return null;
711	        }
712	        String trimmed = email.strip();
713	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
714	            throw new InvalidOwnerFieldsException(List.of("email"));
715	        }
716	        String normalized = trimmed.toLowerCase(Locale.ROOT);
717	        String domain = normalized.substring(normalized.indexOf('@') + 1);
718	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
719	            throw new InvalidOwnerFieldsException(List.of("email"));
720	        }
721	        return normalized;
722	    }
