724	    /**
725	     * Rejects creating an owner whose derived identity key (the SHA-256 hex digest of
726	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}, see {@link OwnerMapper#identityKey})
727	     * exactly equals that of an existing non-deleted owner. Two owners are treated as duplicates only when
728	     * their whole identity keys match, so owners who share a last-name Soundex but differ in telephone or
729	     * email are not duplicates and are admitted (flagged as a soft match instead). Such an owner is rejected
730	     * with a 409, <em>unless</em> the request opts into {@code sharesHousehold}, which bypasses the block
731	     * entirely.
732	     *
733	     * @param owner the owner being created, whose identity key is matched
734	     * @param sharesHousehold whether the request declared the owner a shared-household member
735	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key
736	     */
737	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
738	        if (sharesHousehold) {
739	            return;
740	        }
741	        String identityKey = ownerMapper.identityKey(owner);
742	        boolean duplicate = this.clinicService.findAllOwners().stream()
743	            .filter(existing -> !isDeleted(existing))
744	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
745	        if (duplicate) {
746	            throw new DuplicateOwnerIdentityException(identityKey);
747	        }
748	    }
