750	    /**
751	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
752	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
753	     * owner whose {@link OwnerMapper#identityKey identity key} <em>differs</em> from an existing owner's
754	     * but which shares that owner's last-name {@link OwnerMapper#soundex Soundex code} and postcode. When
755	     * such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
756	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
757	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
758	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
759	     *
760	     * <p>Because the telephone is part of the identity key, two owners with the same last name and postcode
761	     * but different telephones no longer collide on the identity key, so they are admitted as a soft match
762	     * here rather than rejected as a hard household duplicate.
763	     *
764	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the duplicate
765	     * block) is never a <em>suspected</em> duplicate: it is knowingly created as another member of the
766	     * household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
767	     * {@code null} without consulting the existing population.
768	     *
769	     * @param owner the owner being created, whose last-name Soundex and postcode are matched
770	     * @param sharesHousehold whether the request declared the owner a shared-household member
771	     */
772	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
773	        if (sharesHousehold) {
774	            owner.setPossibleDuplicateOf(null);
775	            owner.setPossibleDuplicate(false);
776	            return;
777	        }
778	        String postcode = owner.getPostcode();
779	        Integer matchId = null;
780	        if (postcode != null) {
781	            String identityKey = ownerMapper.identityKey(owner);
782	            String lastNameCode = OwnerIdentity.soundex(owner.getLastName());
783	            for (Owner existing : this.clinicService.findAllOwners()) {
784	                if (!isDeleted(existing)
785	                    && postcode.equals(existing.getPostcode())
786	                    && lastNameCode.equals(OwnerIdentity.soundex(existing.getLastName()))
787	                    && !identityKey.equals(ownerMapper.identityKey(existing))
788	                    && existing.getId() != null
789	                    && (matchId == null || existing.getId() < matchId)) {
790	                    matchId = existing.getId();
791	                }
792	            }
793	        }
794	        owner.setPossibleDuplicateOf(matchId);
795	        owner.setPossibleDuplicate(matchId != null);
796	    }
