846	     *
847	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
848	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
849	     */
850	    /**
851	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
852	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
853	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
854	     * against the date exactly as supplied, before it is rolled forward onto a business day.
855	     *
856	     * @param registrationDate the registration date supplied in the request, may be {@code null}
857	     * @throws FutureRegistrationDateException if the supplied date is after the server date
858	     */
859	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
860	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
861	            throw new FutureRegistrationDateException(registrationDate);
862	        }
863	    }
864	
865	    private LocalDate rollToBusinessDay(LocalDate date) {
866	        LocalDate adjusted = date;
867	        while (!isBusinessDay(adjusted)) {
868	            adjusted = adjusted.plusDays(1);
869	        }
870	        return adjusted;
871	    }
872	
873	    private boolean isBusinessDay(LocalDate date) {
874	        DayOfWeek day = date.getDayOfWeek();
875	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
876	            return false;
877	        }
878	        return !PUBLIC_HOLIDAYS.contains(date);
879	    }
880	
881	    private void rejectDailyLimitReached(LocalDate registrationDate) {
882	        long ownersToday = this.clinicService.findAllOwners().stream()
883	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
884	            .count();
885	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
886	            throw new DailyOwnerLimitExceededException(registrationDate);
887	        }
888	    }
889	
890	    /**
891	     * The number of owners that must already share a {@code registrationDate} before a newly created
892	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
893	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
894	     */
895	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
896	
897	    /**
898	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
899	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
900	     * the same registration date at the time this owner is created. Existing owners are counted by their
901	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
902	     * daily create-limit accumulation.
903	     *
904	     * @param registrationDate the registration date of the owner being created
905	     * @return {@code true} if the day already holds more than the threshold number of owners
906	     */
907	    private boolean isBulkSignupDay(LocalDate registrationDate) {
908	        long ownersToday = this.clinicService.findAllOwners().stream()
909	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
910	            .count();
911	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
912	    }
913	
914	    private void rejectCityAtCapacity(String city) {
915	        String normalizedCity = normalizeForComparison(city);
916	        long ownersInCity = this.clinicService.findAllOwners().stream()
917	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
918	            .count();
919	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
920	            throw new OwnerCityCapacityExceededException(city);
921	        }
922	    }
923	
924	    /**
925	     * The number of owners a city must already hold before a newly created owner in that city is
926	     * flagged as approaching capacity. Once a city already contains at least this many owners (but
927	     * still fewer than {@link #MAX_OWNERS_PER_CITY}), the new owner's {@code capacityWarning} is set.
928	     */
929	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
930	
931	    /**
932	     * Determines whether the owner being created is approaching the per-city capacity limit. The
933	     * warning is raised when the owner's city already contains between {@link
934	     * #CITY_CAPACITY_WARNING_THRESHOLD} and {@code MAX_OWNERS_PER_CITY - 1} owners (inclusive) at the
935	     * time this owner is created; the hard rejection at {@link #MAX_OWNERS_PER_CITY} is unchanged.
936	     * Existing owners' cities are compared case-insensitively with surrounding and repeated internal
937	     * whitespace collapsed (see {@link #normalizeForComparison}), matching {@link #rejectCityAtCapacity}.
938	     *
939	     * @param city the city of the owner being created
940	     * @return {@code true} if the city already holds 40-49 owners
941	     */
942	    private boolean isApproachingCityCapacity(String city) {
943	        String normalizedCity = normalizeForComparison(city);
944	        long ownersInCity = this.clinicService.findAllOwners().stream()
945	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
946	            .count();
947	        return ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY;
948	    }
949	
950	    /**
951	     * Counts how many owners belong to the household the owner being created has just been assigned to,
952	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
953	     * given identifier; the owner being created is added on because it is counted before being persisted.
954	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
955	     * household of one. The value is snapshotted on the owner.
956	     *
957	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
958	     * @return the number of household members, including the owner being created
959	     */
960	    private int countHousehold(String householdId) {
961	        if (householdId == null) {
962	            return 1;
963	        }
964	        long existing = this.clinicService.findAllOwners().stream()
965	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
966	            .count();
967	        return (int) existing + 1;
968	    }
969	
970	    /**
971	     * Computes the membership-level ceiling for the owner being created, snapshotted at creation time.
972	     * A new owner's membership level cannot exceed one above the current maximum membership level among
973	     * their existing household members: the returned cap is that maximum plus one. Existing household
974	     * members are the non-deleted owners already carrying the same {@code householdId}, and their
975	     * membership level is their effective (already-capped) {@link OwnerMapper#membershipLevel level}.
976	     * Returns {@code null} when there is no existing household member, in which case no cap applies.
977	     *
978	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
979	     * @return one above the highest household member's membership level, or {@code null} when none exist
980	     */
981	    private Integer membershipLevelCap(String householdId) {
982	        if (householdId == null) {
983	            return null;
984	        }
985	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
986	            .filter(existing -> !isDeleted(existing))
987	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
988	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
989	            .max();
990	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
991	    }
992	
993	    /**
994	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
995	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
996	     * name is normalized for case- and whitespace-insensitive comparison (see
997	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
998	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
999	     * regardless of creation order, making them members of one household.
1000	     *
1001	     * @param lastName the owner's last name
1002	     * @param postcode the owner's postcode, may be {@code null}
1003	     * @return the deterministic household identifier
1004	     */
1005	    private String householdId(String lastName, String postcode) {
1006	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
1007	        try {
1008	            byte[] digest = MessageDigest.getInstance("SHA-256")
1009	                .digest(key.getBytes(StandardCharsets.UTF_8));
1010	            StringBuilder hex = new StringBuilder();
1011	            for (int i = 0; i < 6; i++) {
1012	                hex.append(String.format("%02x", digest[i]));
1013	            }
1014	            return hex.toString();
1015	        } catch (NoSuchAlgorithmException ex) {
1016	            throw new IllegalStateException("SHA-256 not available", ex);
1017	        }
1018	    }
1019	
1020	    /**
1021	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
1022	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
1023	     * result is lower-cased. A {@code null} value normalizes to the empty string.
1024	     *
1025	     * @param value the value to normalize, may be {@code null}
1026	     * @return the normalized value
1027	     */
1028	    private String normalizeForComparison(String value) {
1029	        if (value == null) {
1030	            return "";
1031	        }
1032	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1033	    }
1034	
1035	    /**
1036	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
1037	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
1038	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
1039	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
1040	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
1041	     * that is stored, returned, and used for every address comparison (household duplicate detection
1042	     * and the shared household id).
1043	     *
1044	     * @param address the raw address value from the submitted owner payload, may be {@code null}
1045	     * @return the normalized address
1046	     */
1047	    /**
1048	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
1049	     * the structured fields over the flat {@code address} input for backward compatibility. When a
1050	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
1051	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
1052	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
1053	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
1054	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
1055	     *
1056	     * @param owner the owner being created, whose raw address fields are normalized in place
1057	     */
1058	    private void applyAddress(Owner owner) {
1059	        String line1 = owner.getAddressLine1();
1060	        if (line1 != null && !line1.isBlank()) {
1061	            String normalizedLine1 = normalizeAddress(line1);
1062	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
1063	            owner.setAddressLine1(normalizedLine1);
1064	            if (!normalizedLine2.isEmpty()) {
1065	                owner.setAddressLine2(normalizedLine2);
1066	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
1067	            } else {
1068	                owner.setAddressLine2(null);
1069	                owner.setAddress(normalizedLine1);
1070	            }
1071	        } else {
1072	            owner.setAddressLine1(null);
1073	            owner.setAddressLine2(null);
1074	            owner.setAddress(normalizeAddress(owner.getAddress()));
1075	        }
1076	    }
1077	
1078	    private String normalizeAddress(String address) {
1079	        if (address == null) {
1080	            return "";
1081	        }
1082	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
1083	        if (collapsed.isEmpty()) {
1084	            return "";
1085	        }
1086	        String[] tokens = collapsed.split(" ");
1087	        StringBuilder normalized = new StringBuilder();
1088	        for (int i = 0; i < tokens.length; i++) {
1089	            if (i > 0) {
1090	                normalized.append(' ');
1091	            }
1092	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1093	        }
1094	        return normalized.toString();
1095	    }
1096	}
